function workViewings(id){return state.viewings.filter(v=>v.work_id===id).sort((a,b)=>new Date(b.watched_at)-new Date(a.watched_at)||new Date(b.created_at)-new Date(a.created_at))}
function latestViewing(id){return workViewings(id)[0]||null}function viewingRatings(id){return state.ratings.filter(r=>r.viewing_id===id)}
function viewingAverage(v){const manual=v?.overall_rating;if(manual!==null&&manual!==''&&manual!==undefined&&Number.isFinite(Number(manual)))return Number(manual);const a=viewingRatings(v.id).map(r=>Number(r.rating)).filter(Number.isFinite);return a.length?a.reduce((s,n)=>s+n,0)/a.length:0}
function autoRating(w){const v=latestViewing(w.id);return v?viewingAverage(v):0}function finalRating(w){return w.rating_override!==null&&w.rating_override!==''&&w.rating_override!==undefined?Number(w.rating_override):autoRating(w)}
