function isShareMode(){return !!PROXY_SHARE_SLUG||new URLSearchParams(location.search).has('share')}
function versionNumber(v){const p=String(v||'0').match(/\d+/g)?.map(Number)||[0];return (p[0]||0)*1000000+(p[1]||0)*1000+(p[2]||0)}
function acceptedVersion(){return BUILD_VERSION}
function candidateReviewRequested(){const version=String(state.release?.candidate_version||'');if(!version)return false;const q=new URLSearchParams(location.search),stored=localStorage.getItem(CANDIDATE_TEST_KEY),ack=localStorage.getItem(CANDIDATE_ACK_KEY);return q.get('candidateTest')==='1'||String(q.get('candidateVersion')||'')===version||String(stored||'')===version||String(ack||'')===version}
function pendingUpdateInfo(){if(!state.currentProfile)return null;if(isAdmin()&&state.release?.candidate_available){const cv=String(state.release.candidate_version||''),status=String(state.release?.candidate_status||'testing'),serverReviewed=!!state.release?.candidate_tested_at,localReviewed=String(localStorage.getItem(CANDIDATE_ACK_KEY)||'')===cv;if(!serverReviewed&&!localReviewed&&!candidateMode()&&status==='testing')return{version:cv,kind:'candidate',notes:state.release.candidate_notes||''}}const stable=state.release?.stable_version||BASELINE_VERSION;if(versionNumber(stable)>versionNumber(BUILD_VERSION))return{version:stable,kind:'stable',notes:state.release.candidate_notes||'يتوفر إصدار أحدث من كادر.'};return null}
