function refreshReleaseUI(){const pending=pendingUpdateInfo(),f=$('#footerVersion');if(f)f.textContent=`كادر • v${visibleVersion()}${candidateMode()?' • تجريبي للمالك':''}${pending?` • v${pending.version} متاح`:''}`;$('#settingsBtn')?.classList.toggle('hidden',!state.currentProfile);refreshUpdateNotice()}
function refreshUpdateNotice(){const info=pendingUpdateInfo();state.pendingUpdate=info;const box=$('#updateNotice');if(!box)return;if(!info){box.classList.add('hidden');if(isAdmin()&&state.release?.candidate_tested_at)clearKadrNotifications();return}box.classList.remove('hidden');const c=info.kind==='candidate';$('#updateNoticeTitle').textContent=c?`نسخة تجريبية v${info.version} جاهزة للمالك`:`تحديث v${info.version} متاح`;$('#updateNoticeText').textContent=c?'لن يبدأ الاختبار قبل موافقتك، ويمكنك أخذ نسخة احتياطية أولًا.':'لن يتفعّل التحديث على هذا الجهاز قبل أن تضغط «تحديث الآن».'}
