async function refreshApp(){const b=$('#refreshBtn');if(b?.classList.contains('refreshing'))return;b?.classList.add('refreshing');try{if(CLOUD_READY)await loadCloud();else{localLoad();route()}toast('تم تحديث البيانات فقط — لم يتم تثبيت أي تحديث')}catch(e){console.error(e);toast('تعذر تحديث البيانات')}finally{setTimeout(()=>b?.classList.remove('refreshing'),700)}}
async function init(){startLiveClock();setupInstallExperience();registerAppServiceWorker();const remember=$('#rememberMe');if(remember)remember.checked=localStorage.getItem(REMEMBER_KEY)!=='0';if(CLOUD_READY){await loadCloud();setTimeout(syncExistingPushSubscription,500);if(isAdmin()&&candidateMode()&&state.release?.candidate_status==='testing'&&!state.release?.candidate_tested_at)setTimeout(()=>markCandidateTested({silent:true}),220);sb.auth.onAuthStateChange(()=>setTimeout(loadCloud,80));['mashhad_profiles','mashhad_works','mashhad_viewings','mashhad_ratings'].forEach(t=>sb.channel('rt-'+t).on('postgres_changes',{event:'*',schema:'public',table:t},()=>loadCloud()).subscribe());sb.channel('rt-kadr-follows').on('postgres_changes',{event:'*',schema:'public',table:'mashhad_follows'},()=>reloadSocialState()).subscribe();sb.channel('rt-kadr-social-notifications').on('postgres_changes',{event:'*',schema:'public',table:'mashhad_social_notifications'},payload=>{reloadSocialState();if(payload.eventType==='INSERT')toast('🔔 '+String(payload.new?.title||'إشعار جديد من شخص تتابعه'))}).subscribe();sb.channel('rt-mashhad-release').on('postgres_changes',{event:'UPDATE',schema:'public',table:'mashhad_app_release'},payload=>{state.release=payload.new||state.release;refreshReleaseUI();if(isAdmin()&&candidateMode()&&state.release?.candidate_status==='testing'&&!state.release?.candidate_tested_at)setTimeout(()=>markCandidateTested({silent:true}),160);const info=pendingUpdateInfo();if(info)notifyUpdateOnce(info)}).subscribe()}else{localLoad();route()}$('#demoNote')?.classList.toggle('hidden',CLOUD_READY);if($('#brandSub'))$('#brandSub').innerHTML=`<span style="display:inline-flex;align-items:center;gap:5px"><span style="width:6px;height:6px;border-radius:50%;background:${CLOUD_READY?'#62b98c':'#d5b24a'}"></span>${CLOUD_READY?'متزامن مباشر':'نسخة محلية'}</span>`;await syncPushPermissionUI()}

function setRoute(params={}){const u=new URL(location.href);u.search='';Object.entries(params).forEach(([k,v])=>v!==undefined&&u.searchParams.set(k,v));history.pushState({},'',u);route()}window.onpopstate=route;
function route(){refreshReleaseUI();const q=new URLSearchParams(location.search),shared=PROXY_SHARE_SLUG||q.get('share'),wantsAdmin=q.get('admin')==='1',wantsDash=q.get('dashboard')==='1',workTarget=q.get('work');document.body.classList.toggle('shareMode',!!shared);if(shared){state.viewProfile=state.profiles.find(x=>String(x.public_slug||'').toLowerCase()===String(shared).toLowerCase()&&x.is_active!==false)||null;renderPublic();return maybeOpenWorkTarget(workTarget)}if(wantsAdmin&&isAdmin())return renderAdmin();if(wantsDash&&state.currentProfile)return renderDashboard();const requested=q.get('u');if(!requested&&!state.currentProfile){state.viewProfile=null;return renderLanding()}const username=(requested||state.currentProfile?.username||'').toLowerCase();state.viewProfile=state.profiles.find(p=>p.username?.toLowerCase()===username&&p.is_active!==false)||null;renderPublic();maybeOpenWorkTarget(workTarget)}
function maybeOpenWorkTarget(id){if(!id)return;const w=state.works.find(x=>String(x.id)===String(id));if(!w||!state.viewProfile||w.owner_id!==state.viewProfile.id)return;setTimeout(()=>{openDetail(w.id);const u=new URL(location.href);u.searchParams.delete('work');history.replaceState({},'',u)},80)}
function renderLanding(){$('#publicView').classList.remove('hidden');$('#dashboardView').classList.add('hidden');$('#adminView').classList.add('hidden');$('#catalogSection').classList.add('hidden');$('#addWorkHomeBtn')?.classList.add('hidden');$('#profileHero').innerHTML=`<div class="badge">✦ منصة تقييمات سينمائية شخصية</div><h1>ذائقتك السينمائية،<br>برابطك الخاص.</h1><p class="lead">قيّم الأفلام والمسلسلات، سجّل كل مشاهدة أو إعادة مشاهدة، واكتب رأيك واختر بين تقييم نهائي سريع أو تقييم مفصل للقصة والتمثيل والإخراج والتصوير والموسيقى والمتعة. شارك صفحتك مع أصدقائك للقراءة فقط.</p><div class="heroactions"><button class="btn primary" onclick="openAuth()">تسجيل الدخول</button></div><div class="hint" style="margin-top:10px">الحسابات الجديدة ينشئها مالك كادر فقط.</div><div class="stats"><div class="stat"><b>10★</b><span>نهائي أو مفصل</span></div><div class="stat"><b>↻</b><span>سجل مشاهدات</span></div><div class="stat"><b>🔗</b><span>رابط شخصي</span></div><div class="stat"><b>🔒</b><span>قراءة فقط للزوار</span></div></div>`;$('#genreFilters').innerHTML='';$('#workGrid').innerHTML=''}
function renderPublic(){const pv=$('#publicView');pv.classList.remove('hidden');$('#dashboardView').classList.add('hidden');$('#adminView').classList.add('hidden');$('#catalogSection').classList.remove('hidden');const p=state.viewProfile,addBtn=$('#addWorkHomeBtn');if(!p){addBtn?.classList.add('hidden');$('#profileHero').innerHTML=`<div class="empty"><h2 style="color:var(--text)">هذه الصفحة غير متاحة</h2><p>قد يكون الرابط غير صحيح أو الحساب غير منشور.</p></div>`;$('#workGrid').innerHTML='';return}const ownPage=!!state.currentProfile&&state.currentProfile.id===p.id&&!isShareMode();addBtn?.classList.toggle('hidden',!ownPage);const works=profileWorks(p.id),avg=avgOf(works);$('#profileHero').innerHTML=`<div class="profiletop"><img class="avatar" src="${esc(p.avatar_url||avatarPlaceholder(p.display_name))}" onerror="this.src='${avatarPlaceholder(p.display_name)}'"><div class="profileinfo"><h1>${esc(p.display_name)}</h1><div class="handle">@${esc(p.username)}</div></div></div>${p.bio?`<p class="bio">${esc(p.bio)}</p>`:''}<div class="profileactions"><button class="btn secondary" onclick="shareProfile('${esc(p.id)}')">↗ مشاركة الصفحة</button>${ownPage?`<button class="btn primary" onclick="setRoute({dashboard:'1'})">لوحة تحكمي</button><button class="btn secondary" onclick="openCommunity('discover')">👥 المجتمع</button>`:state.currentProfile?followActionsHtml(p):''}</div><div class="stats"><div class="stat"><b>${works.length}</b><span>كل الأعمال</span></div><div class="stat"><b>${works.filter(w=>w.kind==='movie').length}</b><span>أفلام</span></div><div class="stat"><b>${works.filter(w=>w.kind==='series').length}</b><span>مسلسلات</span></div><div class="stat"><b>${avg?fmtRating(avg):'—'}</b><span>متوسط التقييم /10</span></div></div>`;renderFilters(works,false);renderPublicGrid()}
function renderFilters(works,dash){const target=dash?'#dashGenreFilters':'#genreFilters',key=dash?'dashGenre':'genre',genres=[...new Set(works.flatMap(workGenres).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ar'));if(state[key]!=='all'&&!genres.includes(state[key]))state[key]='all';$(target).innerHTML=`<button class="chip ${state[key]==='all'?'active':''}" data-genre="all">كل التصنيفات</button>`+genres.map(g=>`<button class="chip ${state[key]===g?'active':''}" data-genre="${esc(g)}">${esc(g)}</button>`).join('');$$(target+' .chip').forEach(b=>b.onclick=()=>{state[key]=b.dataset.genre;renderFilters(works,dash);dash?renderDashboardGrid():renderPublicGrid()})}
function filteredWorks(list,type,genre,query){const q=String(query||'').trim().toLowerCase();return list.filter(w=>w.kind===type&&(genre==='all'||workGenres(w).includes(genre))&&(!q||[w.title,workGenreText(w),sourceCanonical(w.platform),w.notes].some(v=>String(v||'').toLowerCase().includes(q)))).sort((a,b)=>finalRating(b)-finalRating(a)||new Date(b.updated_at)-new Date(a.updated_at))}
function workCard(w,editable=false){const r=finalRating(w),views=workViewings(w.id),latest=views[0],seasonCtx=w.kind==='series'&&viewingSeasonCount(latest)?`<span>•</span><span>${esc(seasonsText(viewingSeasonCount(latest)))}</span>`:'';return `<article class="work" data-id="${w.id}"><div class="poster"><img src="${esc(w.poster_url||posterPlaceholder(w.title,w.kind))}" onerror="this.src='${posterPlaceholder(w.title,w.kind)}'"><div class="posterbadges"><span class="typepill">${typeIcon(w.kind)} ${typeName(w.kind)} · ${esc(statusName(w.status))}</span><span class="score"><b>${r?fmtRating(r):'—'}</b>${r?'<small class="scoreStar" aria-hidden="true">★</small>':''}</span></div></div><div class="workbody"><h3>${esc(w.title)}</h3><div class="meta"><span>${esc(workGenreText(w))}</span><span>•</span><span>${w.release_year||'—'}</span>${w.platform?`<span>•</span>${sourceBadge(w.platform,'compact')}`:''}${seasonCtx}<span>•</span><span>${views.length} مشاهدة</span></div>${w.notes?`<div class="reviewline">${esc(w.notes)}</div>`:''}${editable?`<div class="inlineactions" style="margin-top:10px"><button class="btn secondary" onclick="event.stopPropagation();openWorkForm(state.works.find(x=>x.id==='${w.id}'))">تعديل</button><button class="btn secondary" onclick="event.stopPropagation();openViewingForm('${w.id}')">＋ مشاهدة</button><button class="btn danger" onclick="event.stopPropagation();deleteWork('${w.id}')">حذف</button></div>`:''}</div></article>`}
function bindWorkCards(sel){$$(sel+' .work').forEach(c=>c.onclick=()=>openDetail(c.dataset.id))}
function renderPublicGrid(){const p=state.viewProfile;if(!p)return;const list=filteredWorks(profileWorks(p.id),state.type,state.genre,state.search);$$('#typeSegment button').forEach(b=>b.classList.toggle('active',b.dataset.type===state.type));$('#listTitle').textContent=`${typePlural(state.type)} الأعلى تقييمًا`;$('#workGrid').innerHTML=list.length?list.map(w=>workCard(w)).join(''):`<div class="empty">لا توجد تقييمات في هذا القسم حتى الآن.</div>`;bindWorkCards('#workGrid')}
function renderDashboard(){const p=state.currentProfile;if(!p)return;$('#publicView').classList.add('hidden');$('#dashboardView').classList.remove('hidden');$('#adminView').classList.add('hidden');const works=profileWorks(p.id),avg=avgOf(works),views=state.viewings.filter(v=>v.owner_id===p.id).length;$('#dashboardHero').innerHTML=`<h1>مرحبًا ${esc(p.display_name)} 👋</h1><p class="lead">هذه مساحتك الخاصة لإدارة تقييماتك وسجل مشاهداتك. صفحتك العامة تبقى للقراءة فقط.</p><div class="quickActions"><button class="quickAction" onclick="setRoute({})"><span class="qicon">👁</span><span>صفحتي الرسمية<small>الواجهة التي يراها أصدقاؤك</small></span></button><button class="quickAction" onclick="openProfileForm()"><span class="qicon">✎</span><span>تعديل ملفي<small>الاسم والصورة والنبذة</small></span></button>${isAdmin()?`<button class="quickAction" onclick="setRoute({admin:'1'})"><span class="qicon">⚙</span><span>إدارة المنصة<small>المستخدمون والتحديثات</small></span></button>`:''}</div><div class="dashboardShare"><div class="label">رابطي في كادر</div><div class="row"><input readonly value="${esc(visualShareUrl(p))}"><button class="btn secondary" onclick="copyProfile('${esc(p.id)}')">نسخ</button></div></div><div class="cards"><div class="metric"><b>${works.length}</b><span>كل الأعمال</span></div><div class="metric"><b>${views}</b><span>المشاهدات</span></div><div class="metric"><b>${works.filter(w=>w.kind==='series').length}</b><span>مسلسلات</span></div><div class="metric"><b>${avg?fmtRating(avg):'—'}</b><span>متوسط التقييم /10</span></div></div>`;renderFilters(works,true);renderDashboardGrid()}
function renderDashboardGrid(){const p=state.currentProfile;if(!p)return;const list=filteredWorks(profileWorks(p.id),state.dashType,state.dashGenre,state.dashSearch);$$('#dashTypeSegment button').forEach(b=>b.classList.toggle('active',b.dataset.type===state.dashType));$('#dashGrid').innerHTML=list.length?list.map(w=>workCard(w,true)).join(''):`<div class="empty">لا توجد أعمال في هذا القسم حتى الآن.</div>`;bindWorkCards('#dashGrid')}
function releaseAdminCard(){const r=state.release||{},status=r.candidate_status||'idle',sha=String(r.candidate_git_sha||'').slice(0,8);if(r.candidate_available&&status==='testing'){const tested=!!r.candidate_tested_at;if(!candidateMode())return `<div class="releaseCard"><div class="releaseRow"><div><span class="previewBadge">${r.candidate_files_verified?'✓ GitHub موثّق':'⏳ قيد التحقق'} · بانتظار اختبار المالك</span><h3 style="font-size:25px;margin:8px 0">v${esc(r.candidate_version)}</h3></div><button class="btn primary" onclick="openCandidateBuild()">فتح النسخة التجريبية</button></div><p>الإصدار الحالي للمستخدمين: <b>v${esc(r.stable_version)}</b>${sha?`<br>بصمة الملفات: <span dir="ltr">${esc(sha)}</span>`:''}<br>${esc(r.candidate_notes||'')}</p></div>`;if(!tested)return `<div class="releaseCard"><div class="releaseRow"><div><span class="previewBadge">✓ النسخة مفتوحة للمالك · جاهزة للاعتماد</span><h3 style="font-size:25px;margin:8px 0">v${esc(r.candidate_version)}</h3></div><button class="btn primary" onclick="approveCandidateRelease(this)">✓ اعتماد ونشر</button></div><p>ضغطة واحدة فقط: إذا كان تأكيد الاختبار لم يصل للخادم بعد، يثبته KADR تلقائيًا ثم يعيد التحقق من نفس الملفات وينشر الإصدار.</p></div>`;return `<div class="releaseCard"><div class="releaseRow"><div><span class="previewBadge">✓ تم الاختبار · جاهز للاعتماد</span><h3 style="font-size:25px;margin:8px 0">v${esc(r.candidate_version)}</h3></div><button class="btn primary" onclick="approveCandidateRelease(this)">✓ اعتماد ونشر</button></div><p>ضغطة واحدة فقط: يعيد KADR التحقق من نفس الملفات التي اختبرتها، ثم يعتمد الإصدار وينشره للمستخدمين إذا لم تتغير.</p></div>`}if(r.candidate_available&&status==='approved_waiting_publish'){return `<div class="releaseCard"><div class="releaseRow"><div><span class="previewBadge">✓ معتمد من المدير · جارٍ النشر التلقائي</span><h3 style="font-size:25px;margin:8px 0">v${esc(r.candidate_version)}</h3></div><span class="releaseSpinner" aria-label="جارٍ النشر"></span></div><p>لا تحتاج لأي ضغطة إضافية. سيقوم KADR بترقية نفس ملفات النسخة التي اختبرتها ثم يتحقق منها قبل إرسالها للمستخدمين.</p></div>`}return `<div class="releaseCard"><div class="releaseRow"><div><span class="previewBadge">✓ الإصدار المنشور</span><h3 style="font-size:25px;margin:8px 0">v${esc(r.stable_version||visibleVersion())}</h3></div><button class="btn secondary" onclick="openReleaseForm()">＋ تهيئة تحديث</button></div><p>يرصد KADR candidate.json ومجلد الإصدار المنفصل تلقائيًا. تبقى النسخة الجديدة معزولة عن المستخدمين حتى يختبرها المالك ويعتمدها بضغطة واحدة.</p></div>`}
function renderAdmin(){if(!isAdmin())return setRoute({});$('#publicView').classList.add('hidden');$('#dashboardView').classList.add('hidden');$('#adminView').classList.remove('hidden');const users=state.profiles.filter(p=>p.role!=='admin');$('#adminHero').innerHTML=`<h1>إدارة كادر</h1><p class="lead">إدارة المستخدمين، الروابط العامة، وإصدارات التطبيق بنظام المالك أولًا.</p><div class="cards"><div class="metric"><b>${users.length}</b><span>مستخدم</span></div><div class="metric"><b>${users.filter(x=>x.is_active).length}</b><span>نشط</span></div><div class="metric"><b>${state.works.length}</b><span>تقييمات</span></div><div class="metric"><b>${state.viewings.length}</b><span>مشاهدات</span></div></div><div style="margin-top:14px">${releaseAdminCard()}</div>`;$('#usersTable').innerHTML=users.length?users.map(p=>`<tr><td><b>${esc(p.display_name)}</b><div class="hint">@${esc(p.username)}</div></td><td><span dir="ltr">${esc(visualShareUrl(p))}</span></td><td>${profileWorks(p.id).length}</td><td><span class="status ${p.is_active?'onstatus':'offstatus'}">${p.is_active?'نشط':'موقوف'}</span></td><td>${dateAr(p.created_at)}</td><td><div class="inlineactions"><button class="btn secondary" onclick="setRoute({u:'${esc(p.username)}'})">عرض</button><button class="btn secondary" onclick="toggleUser('${p.id}',${!p.is_active})">${p.is_active?'إيقاف':'تفعيل'}</button><button class="btn ghost" onclick="openResetPassword('${p.id}')">كلمة المرور</button></div></td></tr>`).join(''):`<tr><td colspan="6">لا يوجد مستخدمون بعد.</td></tr>`}

function openAuth(){show('authModal')}
async function login(){const identifier=$('#loginIdentifier').value.trim(),password=$('#loginPassword').value;if(!identifier||!password)return toast('أدخل اسم المستخدم وكلمة المرور');localStorage.setItem(REMEMBER_KEY,$('#rememberMe').checked?'1':'0');const btn=$('#loginBtn');btn.disabled=true;try{if(CLOUD_READY){const r=await fetch(LOGIN_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY},body:JSON.stringify({identifier,password,action:'login'})}),data=await r.json().catch(()=>({}));if(!r.ok||!data.ok){if(data.code==='EMAIL_NOT_CONFIRMED')$('#confirmNote').classList.remove('hidden');return toast(data.code==='ACCOUNT_DISABLED'?'الحساب موقوف':data.code==='NOT_MASHHAD_USER'?'هذا الحساب غير مفعل في كادر':'بيانات الدخول غير صحيحة')}await sb.auth.setSession({access_token:data.session.access_token,refresh_token:data.session.refresh_token});hide('authModal');await loadCloud();setRoute({});toast('تم تسجيل الدخول')}else{const p=state.profiles.find(x=>x.username.toLowerCase()===identifier.toLowerCase()&&x.password===password);if(!p)return toast('بيانات الدخول غير صحيحة');const storage=$('#rememberMe').checked?localStorage:sessionStorage;localStorage.removeItem(LOCAL_SESSION);sessionStorage.removeItem(LOCAL_SESSION);storage.setItem(LOCAL_SESSION,p.id);state.currentProfile=p;hide('authModal');setRoute({});toast('تم تسجيل الدخول')}}catch(e){console.error(e);toast('تعذر تسجيل الدخول')}finally{btn.disabled=false}}
async function resendConfirmation(){const identifier=$('#loginIdentifier').value.trim();if(!identifier)return toast('أدخل اسم المستخدم أو البريد');try{const r=await fetch(LOGIN_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY},body:JSON.stringify({identifier,action:'resend'})});if(!r.ok)throw new Error();toast('تم إرسال رابط التأكيد إن كان الحساب يحتاجه')}catch{toast('تعذر إرسال رابط التأكيد')}}
async function logout(){if(CLOUD_READY)await sb.auth.signOut();else{localStorage.removeItem(LOCAL_SESSION);sessionStorage.removeItem(LOCAL_SESSION)}state.currentProfile=null;state.session=null;hide('settingsModal');setRoute({});toast('تم تسجيل الخروج')}

async function compressImage(file,maxW,maxH,quality=.86){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{let w=img.width,h=img.height,s=Math.min(1,maxW/w,maxH/h);w=Math.max(1,Math.round(w*s));h=Math.max(1,Math.round(h*s));const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);c.toBlob(b=>{URL.revokeObjectURL(url);b?resolve(b):reject(new Error('compress failed'))},'image/jpeg',quality)};img.onerror=e=>{URL.revokeObjectURL(url);reject(e)};img.src=url})}
async function uploadMedia(file,folder,maxW=1400,maxH=1800){if(!file)return'';if(!CLOUD_READY)return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const blob=await compressImage(file,maxW,maxH,.87),path=`${state.currentProfile.id}/${folder}/${uid()}.jpg`;const {error}=await sb.storage.from(MEDIA_BUCKET).upload(path,blob,{contentType:'image/jpeg',upsert:false,cacheControl:'31536000'});if(error)throw error;return sb.storage.from(MEDIA_BUCKET).getPublicUrl(path).data.publicUrl}
function previewInput(input,preview){input.onchange=()=>{const f=input.files?.[0];if(!f){preview.style.display='none';return}preview.src=URL.createObjectURL(f);preview.style.display='block'}}

function openProfileForm(){const p=state.currentProfile;if(!p)return;$('#profileName').value=p.display_name;$('#profileUsername').value=p.username;$('#profileBio').value=p.bio||'';$('#profilePhoto').value='';$('#profilePreview').style.display='none';show('profileModal')}
async function saveProfile(){const p=state.currentProfile;if(!p)return;const name=$('#profileName').value.trim(),username=$('#profileUsername').value.trim().toLowerCase();if(!name||!/^[a-z0-9_]{3,24}$/.test(username))return toast('اسم المستخدم يجب أن يكون 3–24 حرفًا إنجليزيًا/رقمًا/_');const f=$('#profilePhoto').files?.[0];try{const avatar=f?await uploadMedia(f,'avatars',700,700):p.avatar_url,payload={display_name:name,username,bio:$('#profileBio').value.trim(),avatar_url:avatar};if(CLOUD_READY){const {error}=await sb.from('mashhad_profiles').update(payload).eq('id',p.id);if(error)throw error;await loadCloud()}else{Object.assign(p,payload);localSave()}hide('profileModal');renderDashboard();toast('تم حفظ الملف الشخصي')}catch(e){console.error(e);toast(String(e?.message||'تعذر حفظ الملف'))}}
function scoreOptions(v=''){const current=v===null||v===undefined?'':String(v),vals=Array.from({length:19},(_,i)=>10-i*.5);return `<option value="" ${current===''?'selected':''}>— بدون تقييم —</option>`+vals.map(n=>`<option value="${n}" ${Number(current)===n&&current!==''?'selected':''}>${fmtRating(n)}</option>`).join('')}
function renderCriteria(container,preview,values={}){$(container).innerHTML=CRITERIA.map(([k,label])=>`<div class="criterion"><label>${label}</label><select data-criterion="${k}">${scoreOptions(values[k]??'')}</select></div>`).join('');$$(container+' select').forEach(s=>s.onchange=()=>updateCriteriaAvg(container,preview));updateCriteriaAvg(container,preview)}
function updateCriteriaAvg(container,preview){const a=$$(container+' select').map(s=>s.value===''?null:Number(s.value)).filter(Number.isFinite);$(preview).textContent=a.length?fmtRating(a.reduce((x,y)=>x+y,0)/a.length):'—'}
function currentCriteriaValues(viewing){const vals={};if(viewing)viewingRatings(viewing.id).forEach(r=>vals[r.criterion]=Number(r.rating));return vals}
function hasDetailedRatings(viewing){return !!(viewing&&viewingRatings(viewing.id).length)}
function setDetailedMode(toggleId,wrapId,enabled){const t=$(toggleId),w=$(wrapId);if(t)t.checked=!!enabled;if(w)w.classList.toggle('hidden',!enabled)}
function optionalRatingValue(selector){const v=$(selector)?.value;return v===''||v===undefined||v===null?null:Number(v)}
function hasCriteriaValues(container){return $$(container+' select').some(s=>s.value!=='')}
function toggleSeriesFields(kind,prefix){const isSeries=kind==='series';$$(prefix).forEach(e=>e.classList.toggle('hidden',!isSeries))}
function openWorkForm(w=null){if(!state.currentProfile)return openAuth();const latest=w?latestViewing(w.id):null;$('#workModalTitle').textContent=w?'تعديل العمل والتقييم الأخير':'إضافة تقييم جديد';$('#workId').value=w?.id||'';$('#workTitle').value=w?.title||'';$('#workKind').value=w?.kind||'movie';renderWorkGenrePicker(w?workGenres(w):['دراما']);$('#workYear').value=w?.release_year||new Date().getFullYear();$('#workPlatform').value=sourceCanonical(w?.platform||'');renderWorkSourcePicker($('#workKind').value,w?.platform||'');$('#workStatus').value=w?.status||'completed';$('#workOverride').value=w?.rating_override??'';$('#workNotes').value=w?.notes||'';$('#workPoster').value='';$('#workPreview').style.display='none';$('#workWatchedAt').value=toLocalInput(latest?.watched_at);$('#workSeasonsWatched').value=viewingSeasonCount(latest)||'';$('#workEpisode').value=latest?.episode_number||'';$('#workViewingOverall').value=latest?.overall_rating??'';renderCriteria('#workCriteria','#workAvgPreview',currentCriteriaValues(latest));setDetailedMode('#workDetailedToggle','#workCriteriaWrap',hasDetailedRatings(latest));toggleSeriesFields($('#workKind').value,'.seriesOnly');show('workModal')}
async function upsertCriteria(workId,viewingId,container,enabled=true,ownerId=state.currentProfile.id){const rows=enabled?$$(container+' select').filter(s=>s.value!=='').map(s=>({work_id:workId,viewing_id:viewingId,owner_id:ownerId,criterion:s.dataset.criterion,rating:Number(s.value),notes:''})):[];if(CLOUD_READY){const {error:de}=await sb.from('mashhad_ratings').delete().eq('viewing_id',viewingId);if(de)throw de;if(rows.length){const {error}=await sb.from('mashhad_ratings').insert(rows);if(error)throw error}}else{state.ratings=state.ratings.filter(r=>r.viewing_id!==viewingId);rows.forEach(r=>state.ratings.push({id:uid(),...r,created_at:new Date().toISOString(),updated_at:new Date().toISOString()}))}}
async function saveWork(){const id=$('#workId').value,old=state.works.find(w=>w.id===id);if(old&&!canEdit(old))return toast('لا تملك صلاحية التعديل');const title=$('#workTitle').value.trim(),genres=selectedWorkGenres();if(!title||!genres.length)return toast('أدخل اسم العمل واختر تصنيفًا واحدًا على الأقل');const btn=$('#saveWorkBtn');btn.disabled=true;try{const f=$('#workPoster').files?.[0],poster=f?await uploadMedia(f,'posters',1200,1800):(old?.poster_url||''),payload={title,kind:$('#workKind').value,genre:genres[0],genres,release_year:$('#workYear').value?Number($('#workYear').value):null,platform:selectedWorkSourceValue(),poster_url:poster,notes:$('#workNotes').value.trim(),rating_override:$('#workOverride').value===''?null:Number($('#workOverride').value),status:$('#workStatus').value};const detailed=$('#workDetailedToggle').checked,overall=optionalRatingValue('#workViewingOverall');if(overall!==null&&(overall<1||overall>10)){btn.disabled=false;return toast('التقييم يجب أن يكون من 1 إلى 10')}const seriesCount=$('#workKind').value==='series'&&$('#workSeasonsWatched').value?Number($('#workSeasonsWatched').value):null;if($('#workKind').value==='series'&&['completed','watching','dropped'].includes($('#workStatus').value)&&(overall!==null||detailed)&&!seriesCount){btn.disabled=false;return toast('حدد عدد المواسم التي شاهدتها')}if($('#workStatus').value==='completed'&&overall===null&&!(detailed&&hasCriteriaValues('#workCriteria'))&&payload.rating_override===null){btn.disabled=false;return toast('أدخل التقييم النهائي أو أضف تقييمًا مفصلًا')}let workId=id;if(CLOUD_READY){if(id){const {error}=await sb.from('mashhad_works').update(payload).eq('id',id);if(error)throw error}else{const {data,error}=await sb.from('mashhad_works').insert({...payload,owner_id:state.currentProfile.id}).select('id').single();if(error)throw error;workId=data.id}const ownerId=old?.owner_id||state.currentProfile.id;let v=old?latestViewing(workId):null;const vpayload={work_id:workId,owner_id:ownerId,watched_at:new Date($('#workWatchedAt').value||Date.now()).toISOString(),season_number:$('#workKind').value==='series'&&$('#workSeasonsWatched').value?Number($('#workSeasonsWatched').value):null,seasons_watched:$('#workKind').value==='series'&&$('#workSeasonsWatched').value?Number($('#workSeasonsWatched').value):null,episode_number:$('#workKind').value==='series'&&$('#workEpisode').value?Number($('#workEpisode').value):null,status:$('#workStatus').value,notes:'',overall_rating:overall};let viewingId=v?.id;if(viewingId){const {error}=await sb.from('mashhad_viewings').update(vpayload).eq('id',viewingId);if(error)throw error}else{const {data,error}=await sb.from('mashhad_viewings').insert(vpayload).select('id').single();if(error)throw error;viewingId=data.id}await upsertCriteria(workId,viewingId,'#workCriteria',detailed,ownerId);await loadCloud()}else{const now=new Date().toISOString();if(old){Object.assign(old,payload,{updated_at:now});workId=old.id}else{workId=uid();state.works.unshift({id:workId,owner_id:state.currentProfile.id,...payload,created_at:now,updated_at:now})}const ownerId=old?.owner_id||state.currentProfile.id;let v=old?latestViewing(workId):null;if(!v){v={id:uid(),work_id:workId,owner_id:ownerId,created_at:now,updated_at:now};state.viewings.push(v)}Object.assign(v,{watched_at:new Date($('#workWatchedAt').value||Date.now()).toISOString(),season_number:$('#workKind').value==='series'&&$('#workSeasonsWatched').value?Number($('#workSeasonsWatched').value):null,seasons_watched:$('#workKind').value==='series'&&$('#workSeasonsWatched').value?Number($('#workSeasonsWatched').value):null,episode_number:$('#workKind').value==='series'&&$('#workEpisode').value?Number($('#workEpisode').value):null,status:$('#workStatus').value,notes:'',overall_rating:overall,updated_at:now});await upsertCriteria(workId,v.id,'#workCriteria',detailed,ownerId);localSave();renderDashboard()}hide('workModal');toast('تم حفظ التقييم')}catch(e){console.error(e);toast('تعذر حفظ التقييم')}finally{btn.disabled=false}}
function openViewingForm(workId,v=null){const w=state.works.find(x=>x.id===workId);if(!w||!canEdit(w))return;$('#viewingModalTitle').textContent=v?'تعديل مشاهدة':'إضافة مشاهدة جديدة';$('#viewingId').value=v?.id||'';$('#viewingWorkId').value=workId;$('#viewingWatchedAt').value=toLocalInput(v?.watched_at);$('#viewingStatus').value=v?.status||w.status||'completed';$('#viewingSeasonsWatched').value=viewingSeasonCount(v)||'';$('#viewingEpisode').value=v?.episode_number||'';$('#viewingNotes').value=v?.notes||'';$('#viewingOverall').value=v?.overall_rating??'';renderCriteria('#viewingCriteria','#viewingAvgPreview',currentCriteriaValues(v));setDetailedMode('#viewingDetailedToggle','#viewingCriteriaWrap',hasDetailedRatings(v));toggleSeriesFields(w.kind,'.viewingSeriesOnly');show('viewingModal')}
async function saveViewing(){const id=$('#viewingId').value,workId=$('#viewingWorkId').value,w=state.works.find(x=>x.id===workId);if(!w||!canEdit(w))return;const payload={work_id:workId,owner_id:w.owner_id,watched_at:new Date($('#viewingWatchedAt').value||Date.now()).toISOString(),season_number:w.kind==='series'&&$('#viewingSeasonsWatched').value?Number($('#viewingSeasonsWatched').value):null,seasons_watched:w.kind==='series'&&$('#viewingSeasonsWatched').value?Number($('#viewingSeasonsWatched').value):null,episode_number:w.kind==='series'&&$('#viewingEpisode').value?Number($('#viewingEpisode').value):null,status:$('#viewingStatus').value,notes:$('#viewingNotes').value.trim(),overall_rating:optionalRatingValue('#viewingOverall')};const detailed=$('#viewingDetailedToggle').checked,btn=$('#saveViewingBtn');if(payload.overall_rating!==null&&(payload.overall_rating<1||payload.overall_rating>10))return toast('التقييم يجب أن يكون من 1 إلى 10');if(w.kind==='series'&&['completed','watching','dropped'].includes(payload.status)&&(payload.overall_rating!==null||detailed)&&!payload.seasons_watched)return toast('حدد عدد المواسم التي شاهدتها');if(payload.status==='completed'&&payload.overall_rating===null&&!(detailed&&hasCriteriaValues('#viewingCriteria')))return toast('أدخل التقييم النهائي أو أضف تقييمًا مفصلًا');btn.disabled=true;try{let viewingId=id;if(CLOUD_READY){if(id){const {error}=await sb.from('mashhad_viewings').update(payload).eq('id',id);if(error)throw error}else{const {data,error}=await sb.from('mashhad_viewings').insert(payload).select('id').single();if(error)throw error;viewingId=data.id}await upsertCriteria(workId,viewingId,'#viewingCriteria',detailed,w.owner_id);await sb.from('mashhad_works').update({status:payload.status}).eq('id',workId);await loadCloud()}else{const now=new Date().toISOString(),old=state.viewings.find(v=>v.id===id);if(old)Object.assign(old,payload,{updated_at:now});else{viewingId=uid();state.viewings.push({id:viewingId,...payload,created_at:now,updated_at:now})}await upsertCriteria(workId,viewingId,'#viewingCriteria',detailed,w.owner_id);w.status=payload.status;localSave()}hide('viewingModal');hide('detailModal');openDetail(workId);toast('تم حفظ المشاهدة')}catch(e){console.error(e);toast('تعذر حفظ المشاهدة')}finally{btn.disabled=false}}
function viewingCard(v,w){const avg=viewingAverage(v),rs=viewingRatings(v.id),manual=v.overall_rating!==null&&v.overall_rating!==undefined&&v.overall_rating!=='';const seasonCtx=w.kind==='series'&&viewingSeasonCount(v)?` · تقييم ${seriesRatingContext(v)}`:'';return `<div class="viewingCard"><div class="viewingHead"><div><b>${dateTimeAr(v.watched_at)}</b><div class="viewingMeta">${statusIcon(v.status)} ${statusName(v.status)}${seasonCtx}${w.kind==='series'&&v.episode_number?` · آخر حلقة ${v.episode_number}`:''}${manual?' · تقييم نهائي':''}</div></div><div class="viewingScore">★ ${avg||avg===0?fmtRating(avg):'—'}</div></div>${v.notes?`<div class="viewingNote">${esc(v.notes)}</div>`:''}${rs.length?`<div class="viewingBreakdown">${rs.map(r=>`<div class="miniCrit"><span>${esc(criterionLabel(r.criterion))}</span><b>${fmtRating(r.rating)}</b></div>`).join('')}</div>`:`<div class="finalOnlyNote">${manual?'تقييم نهائي فقط — بدون تقييمات تفصيلية':'لم تتم إضافة تقييمات تفصيلية'}</div>`}${canEdit(w)?`<div class="viewingActions"><button class="btn secondary" onclick="openViewingForm('${w.id}',state.viewings.find(x=>x.id==='${v.id}'))">تعديل</button><button class="btn danger" onclick="deleteViewing('${v.id}','${w.id}')">حذف المشاهدة</button></div>`:''}</div>`}
function openDetail(id){const w=state.works.find(x=>x.id===id);if(!w)return;const r=finalRating(w),views=workViewings(id),latest=views[0],hasPoster=!!String(w.poster_url||'').trim();const media=hasPoster?`<div class="detailPoster"><img src="${esc(w.poster_url)}" onerror="this.closest('.detailPoster').classList.add('brokenPoster');this.style.display='none'"><button class="close detailClose" onclick="hide('detailModal')">×</button></div>`:`<div class="detailNoPoster"><div class="detailNoPosterMark">K</div><button class="close detailClose" onclick="hide('detailModal')">×</button></div>`;$('#detailContent').innerHTML=`${media}<div class="detailInfo"><div class="detailrow"><div class="detailTitleBlock"><div class="badge">${typeIcon(w.kind)} ${typeName(w.kind)} · ${esc(workGenreText(w))}</div><h2>${esc(w.title)}</h2><div class="detailPills"><span class="statuspill">${w.release_year||'—'}</span> ${w.platform?`<span class="statuspill sourceDetailPill">${sourceBadge(w.platform,'detail')}</span>`:''} <span class="statuspill">${statusName(w.status)}</span> <span class="statuspill">${views.length} مشاهدة</span>${w.kind==='series'&&viewingSeasonCount(latest)?` <span class="statuspill">${esc(seriesRatingContext(latest))}</span>`:''}</div></div><div class="bigscore"><b>${r||r===0?fmtRating(r):'—'}</b></div></div></div>${w.notes?`<div class="reviewbox">${esc(w.notes)}</div>`:''}<div class="sectionhead detailSectionHead" style="margin-top:18px"><div><h3>سجل المشاهدات</h3><p>${latest?`آخر مشاهدة ${dateAr(latest.watched_at)}`:'لا توجد مشاهدة مسجلة'}</p></div>${canEdit(w)?`<button class="btn primary" onclick="openViewingForm('${w.id}')">＋ مشاهدة جديدة</button>`:''}</div>${views.length?views.map(v=>viewingCard(v,w)).join(''):`<div class="empty">لا توجد مشاهدات مسجلة.</div>`}${canEdit(w)?`<div class="detailactions"><button class="btn secondary" onclick="hide('detailModal');openWorkForm(state.works.find(x=>x.id==='${w.id}'))">✎ تعديل العمل</button><button class="btn danger" onclick="deleteWork('${w.id}')">حذف العمل</button></div>`:''}`;show('detailModal')}
async function deleteViewing(id,workId){const v=state.viewings.find(x=>x.id===id),w=state.works.find(x=>x.id===workId);if(!v||!w||!canEdit(w)||!confirm('حذف هذه المشاهدة وتقييمها؟'))return;try{if(CLOUD_READY){const {error}=await sb.from('mashhad_viewings').delete().eq('id',id);if(error)throw error;await loadCloud()}else{state.viewings=state.viewings.filter(x=>x.id!==id);state.ratings=state.ratings.filter(r=>r.viewing_id!==id);localSave()}hide('detailModal');openDetail(workId);toast('تم حذف المشاهدة')}catch(e){console.error(e);toast('تعذر الحذف')}}
async function deleteWork(id){const w=state.works.find(x=>x.id===id);if(!w||!canEdit(w)||!confirm(`حذف «${w.title}» وسجل مشاهداته؟`))return;try{if(CLOUD_READY){const {error}=await sb.from('mashhad_works').delete().eq('id',id);if(error)throw error;await loadCloud()}else{state.works=state.works.filter(x=>x.id!==id);state.viewings=state.viewings.filter(v=>v.work_id!==id);state.ratings=state.ratings.filter(r=>r.work_id!==id);localSave()}hide('detailModal');renderDashboard();toast('تم حذف العمل')}catch(e){console.error(e);toast('تعذر الحذف')}}

async function adminCall(body){const session=(await sb.auth.getSession()).data.session;if(!session)throw new Error('NO_SESSION');const r=await fetch(ADMIN_USERS_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY,'Authorization':`Bearer ${session.access_token}`},body:JSON.stringify(body)}),data=await r.json().catch(()=>({}));if(!r.ok||!data.ok)throw new Error(data.error||'REQUEST_FAILED');return data}
async function createUser(){if(!isAdmin())return;const body={action:'create',display_name:$('#adminNewDisplayName').value.trim(),username:$('#adminNewUsername').value.trim().toLowerCase(),email:$('#adminNewEmail').value.trim().toLowerCase(),password:$('#adminNewPassword').value};if(!body.display_name||!/^[a-z0-9_]{3,24}$/.test(body.username)||!body.email||body.password.length<8)return toast('أكمل البيانات وتأكد أن كلمة المرور 8 أحرف على الأقل');const b=$('#adminCreateUserBtn');b.disabled=true;try{if(CLOUD_READY){await adminCall(body);await loadCloud()}else{if(state.profiles.some(p=>p.username===body.username))throw new Error('USERNAME_TAKEN');state.profiles.push({id:uid(),username:body.username,public_slug:body.username+'-cinema',display_name:body.display_name,bio:'',avatar_url:'',role:'creator',is_active:true,created_at:new Date().toISOString(),password:body.password});localSave();renderAdmin()}hide('adminCreateUserModal');toast('تم إنشاء الحساب')}catch(e){console.error(e);toast(e.message==='USERNAME_TAKEN'?'اسم المستخدم مستخدم':e.message==='EMAIL_TAKEN'?'البريد مستخدم بالفعل':'تعذر إنشاء الحساب')}finally{b.disabled=false}}
async function toggleUser(id,active){if(!isAdmin())return;try{if(CLOUD_READY){await adminCall({action:'set-active',user_id:id,is_active:active});await loadCloud()}else{const p=state.profiles.find(x=>x.id===id);if(p)p.is_active=active;localSave();renderAdmin()}toast(active?'تم تفعيل المستخدم':'تم إيقاف المستخدم')}catch(e){console.error(e);toast('تعذر تعديل الحساب')}}
function openResetPassword(id){if(!isAdmin())return;$('#resetUserId').value=id;$('#resetPasswordValue').value='';show('resetPasswordModal')}
async function resetPassword(){const id=$('#resetUserId').value,password=$('#resetPasswordValue').value;if(password.length<8)return toast('كلمة المرور 8 أحرف على الأقل');try{if(CLOUD_READY)await adminCall({action:'reset-password',user_id:id,password});else{const p=state.profiles.find(x=>x.id===id);if(p)p.password=password;localSave()}hide('resetPasswordModal');toast('تم تعيين كلمة المرور الجديدة')}catch(e){console.error(e);toast('تعذر إعادة تعيين كلمة المرور')}}

function openSettings(){const p=state.currentProfile;if(!p)return openAuth();$('#publicLinkPreview').value=visualShareUrl(p);$('#publicSlugInput').value=p.public_slug||p.username||'';$('#ownerAppLinkBlock').classList.toggle('hidden',!isAdmin());$('#settingsAdminBtn').classList.toggle('hidden',!isAdmin());$('#ownerAppLinkPreview').value=`${location.origin}/KADR/`;show('settingsModal')}
async function savePublicSlug(){const p=state.currentProfile,slug=$('#publicSlugInput').value.trim().toLowerCase();if(!p)return;if(!/^[a-z0-9][a-z0-9_-]{2,38}[a-z0-9]$/.test(slug))return toast('استخدم 4–40 حرفًا: a-z و0-9 و- و_');try{if(CLOUD_READY){const {error}=await sb.from('mashhad_profiles').update({public_slug:slug}).eq('id',p.id);if(error)throw error;await loadCloud()}else{p.public_slug=slug;localSave()}openSettings();toast('تم تحديث الرابط الشخصي')}catch(e){console.error(e);toast('الاسم مستخدم أو غير صالح')}}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('تم النسخ')}catch{const i=document.createElement('textarea');i.value=t;document.body.appendChild(i);i.select();document.execCommand('copy');i.remove();toast('تم النسخ')}}
async function copyProfile(id){const p=profileByKey(id);if(p)await copyText(shareUrl(p))}
async function shareProfile(id){const p=profileByKey(id);if(!p)return;const url=shareUrl(p);try{if(navigator.share){await navigator.share({title:`تقييمات ${p.display_name} على كادر`,text:'شاهد تقييماتي للأفلام والمسلسلات على كادر',url});return}await copyText(url)}catch(e){if(e?.name!=='AbortError')toast('تعذر فتح المشاركة')}}


function myFollow(targetId){return state.follows.find(f=>f.follower_id===state.currentProfile?.id&&f.following_id===targetId)||null}
function incomingFollowerCount(id){return state.follows.filter(f=>f.following_id===id).length}
function followingCount(id){return state.follows.filter(f=>f.follower_id===id).length}
function unreadSocialCount(){return state.socialNotifications.filter(n=>!n.read_at).length}
function refreshCommunityBadge(){const n=unreadSocialCount(),b=$('#communityBadge'),t=$('#communityTabBadge'),btn=$('#communityBtn');btn?.classList.toggle('hidden',!state.currentProfile);for(const el of [b,t])if(el){el.textContent=String(n);el.classList.toggle('hidden',!n)}}
function followActionsHtml(p){const f=myFollow(p.id);if(!f)return `<button class="btn primary followBtn" onclick="toggleFollow('${p.id}',event)">＋ متابعة</button>`;return `<button class="btn secondary followBtn following" onclick="toggleFollow('${p.id}',event)">✓ أتابعه</button><button class="btn ${f.notify_new_works?'primary':'secondary'} bellFollowBtn" onclick="toggleFollowNotify('${p.id}',event)" title="إشعار عند إضافة عمل جديد">${f.notify_new_works?'🔔 التنبيه مفعل':'🔕 فعّل التنبيه'}</button>`}
function personRow(p){const f=myFollow(p.id),works=profileWorks(p.id).length;return `<div class="personRow"><button class="personIdentity" onclick="hide('communityModal');setRoute({u:'${esc(p.username)}'})"><img src="${esc(p.avatar_url||avatarPlaceholder(p.display_name))}" onerror="this.src='${avatarPlaceholder(p.display_name)}'"><span><b>${esc(p.display_name)}</b><small dir="ltr">@${esc(p.username)}</small><em>${works} عمل</em></span></button><div class="personActions">${f?`<button class="iconToggle ${f.notify_new_works?'active':''}" onclick="toggleFollowNotify('${p.id}',event)" title="إشعار عند إضافة عمل">${f.notify_new_works?'🔔':'🔕'}</button>`:''}<button class="btn ${f?'secondary':'primary'} compactBtn" onclick="toggleFollow('${p.id}',event)">${f?'✓ أتابعه':'＋ متابعة'}</button></div></div>`}
function renderCommunityDiscover(){const q=String($('#communitySearchInput')?.value||'').trim().toLowerCase(),me=state.currentProfile?.id;let users=state.profiles.filter(p=>p.id!==me&&p.is_active!==false);if(q)users=users.filter(p=>String(p.username||'').toLowerCase().includes(q)||String(p.display_name||'').toLowerCase().includes(q));else users=users.slice(0,12);$('#communitySearchResults').innerHTML=users.length?users.slice(0,30).map(personRow).join(''):`<div class="empty compactEmpty">لا يوجد مستخدم بهذا الاسم.</div>`}
function renderFollowingList(){const ids=state.follows.filter(f=>f.follower_id===state.currentProfile?.id).map(f=>f.following_id),users=ids.map(id=>state.profiles.find(p=>p.id===id)).filter(Boolean);$('#followingList').innerHTML=users.length?users.map(personRow).join(''):`<div class="empty compactEmpty">لا تتابع أحدًا بعد. ابحث عن أصدقائك من تبويب «اكتشف».</div>`}
function socialNotificationRow(n){const actor=state.profiles.find(p=>p.id===n.actor_id),work=state.works.find(w=>w.id===n.work_id);return `<button class="socialNotification ${n.read_at?'':'unread'}" onclick="openSocialNotification('${n.id}')"><img src="${esc(actor?.avatar_url||avatarPlaceholder(actor?.display_name||'K'))}" onerror="this.src='${avatarPlaceholder(actor?.display_name||'K')}'"><span><b>${esc(n.title)}</b><small>${esc(n.body)}</small><em>${dateTimeAr(n.created_at)}</em></span>${work?.poster_url?`<img class="notificationPoster" src="${esc(work.poster_url)}">`:''}</button>`}
function renderSocialNotifications(){const list=state.socialNotifications;$('#socialNotificationsList').innerHTML=list.length?list.map(socialNotificationRow).join(''):`<div class="empty compactEmpty">لا توجد إشعارات متابعة حتى الآن.</div>`;refreshCommunityBadge()}
function renderCommunity(){const tab=state.communityTab||'discover';$$('[data-community-tab]').forEach(b=>b.classList.toggle('active',b.dataset.communityTab===tab));$('#communityDiscover').classList.toggle('hidden',tab!=='discover');$('#communityFollowing').classList.toggle('hidden',tab!=='following');$('#communityNotifications').classList.toggle('hidden',tab!=='notifications');if(tab==='discover')renderCommunityDiscover();if(tab==='following')renderFollowingList();if(tab==='notifications')renderSocialNotifications();refreshCommunityBadge()}
function openCommunity(tab='discover'){if(!state.currentProfile)return openAuth();state.communityTab=tab;show('communityModal');renderCommunity();setTimeout(()=>tab==='discover'&&$('#communitySearchInput')?.focus(),100)}
async function reloadSocialState(){if(!CLOUD_READY||!state.currentProfile)return;const [{data:follows,error:fe},{data:notes,error:ne}]=await Promise.all([sb.from('mashhad_follows').select('*').order('created_at',{ascending:false}),sb.from('mashhad_social_notifications').select('*').order('created_at',{ascending:false}).limit(100)]);if(fe||ne){console.warn(fe||ne);return}state.follows=follows||[];state.socialNotifications=notes||[];refreshCommunityBadge();if($('#communityModal')?.classList.contains('show'))renderCommunity()}
async function toggleFollow(targetId,event){event?.stopPropagation();if(!state.currentProfile)return openAuth();const f=myFollow(targetId);try{if(f){const {error}=await sb.from('mashhad_follows').delete().eq('follower_id',state.currentProfile.id).eq('following_id',targetId);if(error)throw error;toast('تم إلغاء المتابعة')}else{const {error}=await sb.from('mashhad_follows').insert({follower_id:state.currentProfile.id,following_id:targetId,notify_new_works:false});if(error)throw error;toast('تمت المتابعة')};await reloadSocialState();if(state.viewProfile?.id===targetId)renderPublic()}catch(e){console.error(e);toast('تعذر تعديل المتابعة')}}
async function toggleFollowNotify(targetId,event){event?.stopPropagation();const f=myFollow(targetId);if(!f)return toast('تابع المستخدم أولًا');const next=!f.notify_new_works;try{const {error}=await sb.from('mashhad_follows').update({notify_new_works:next}).eq('follower_id',state.currentProfile.id).eq('following_id',targetId);if(error)throw error;await reloadSocialState();if(state.viewProfile?.id===targetId)renderPublic();if(next){if(Notification.permission==='granted')await ensurePushSubscriptionRegistered({createIfMissing:true});else toast('تم تفعيل التنبيه داخل KADR — فعّل إشعارات الجهاز ليصلك خارجه')}else toast('تم إيقاف تنبيهات هذا المستخدم')}catch(e){console.error(e);toast('تعذر تعديل التنبيه')}}
async function openSocialNotification(id){const n=state.socialNotifications.find(x=>x.id===id);if(!n)return;if(!n.read_at){const now=new Date().toISOString();n.read_at=now;refreshCommunityBadge();sb.from('mashhad_social_notifications').update({read_at:now}).eq('id',id).then(()=>{}).catch(console.warn)}const actor=state.profiles.find(p=>p.id===n.actor_id);hide('communityModal');if(actor)setRoute({u:actor.username,work:n.work_id})}
async function markAllSocialRead(){const unread=state.socialNotifications.filter(n=>!n.read_at);if(!unread.length)return toast('كل الإشعارات مقروءة');const now=new Date().toISOString();try{const {error}=await sb.from('mashhad_social_notifications').update({read_at:now}).eq('recipient_id',state.currentProfile.id).is('read_at',null);if(error)throw error;unread.forEach(n=>n.read_at=now);renderSocialNotifications();toast('تم تحديد الكل كمقروء')}catch(e){console.error(e);toast('تعذر تحديث الإشعارات')}}

function openReleaseForm(){if(!isAdmin())return;const n=versionNumber(state.release?.stable_version||'1.0');$('#releaseVersion').value=(Math.round((n+.1)*10)/10).toFixed(1);$('#releaseNotes').value='';show('releaseModal')}
async function releaseCall(body,{retries=1}={}){const session=(await sb.auth.getSession()).data.session;if(!session)throw Object.assign(new Error('NO_SESSION'),{code:'NO_SESSION'});let last;for(let attempt=0;attempt<=retries;attempt++){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),18000);try{const r=await fetch(RELEASE_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY,'Authorization':`Bearer ${session.access_token}`},body:JSON.stringify(body),signal:controller.signal}),data=await r.json().catch(()=>({}));clearTimeout(timer);if(!r.ok||!data.ok){const e=new Error(data.detail||data.error||'REQUEST_FAILED');e.code=data.error||'REQUEST_FAILED';e.detail=data.detail||'';const retry409=r.status===409&&['GITHUB_NOT_READY','CANDIDATE_NOT_READY','CANDIDATE_NOT_TESTED'].includes(String(data.error||''));if((r.status<500&&!retry409)||attempt===retries)throw e;last=e}else{return data}}catch(e){clearTimeout(timer);last=e;if(attempt===retries)throw e;await new Promise(r=>setTimeout(r,650*(attempt+1)))}}throw last||new Error('REQUEST_FAILED')}
function openCandidateBuild(){const version=String(state.release?.candidate_version||BUILD_VERSION);localStorage.setItem(CANDIDATE_TEST_KEY,version);localStorage.setItem(CANDIDATE_ACK_KEY,version);$('#updateNotice')?.classList.add('hidden');state.pendingUpdate=null;clearKadrNotifications();const path=String(state.release?.candidate_path||'candidate'),v=encodeURIComponent(version),stamp=Date.now();location.href=path==='root'||path==='release'?`/KADR/?candidateTest=1&candidateVersion=${v}&forceUpdate=1&_=${stamp}`:`/KADR/candidate/?candidateTest=1&candidateVersion=${v}&_=${stamp}`}
function returnToMyHome(){setRoute({})}
async function markCandidateTested({silent=false}={}){if(!CLOUD_READY||!isAdmin()||!candidateMode()||candidateTestInFlight)return false;if(state.release?.candidate_status!=='testing')return !!state.release?.candidate_tested_at;if(state.release?.candidate_tested_at){localStorage.removeItem(CANDIDATE_TEST_KEY);$('#updateNotice')?.classList.add('hidden');state.pendingUpdate=null;await clearKadrNotifications();returnToMyHome();return true}candidateTestInFlight=true;try{const version=String(state.release.candidate_version);localStorage.setItem(CANDIDATE_TEST_KEY,version);localStorage.setItem(CANDIDATE_ACK_KEY,version);await releaseCall({action:'mark-tested',version},{retries:3});const rel=await refreshReleaseState();if(!rel?.candidate_tested_at)throw Object.assign(new Error('TEST_STATE_NOT_CONFIRMED'),{code:'TEST_STATE_NOT_CONFIRMED'});localStorage.removeItem(CANDIDATE_TEST_KEY);$('#updateNotice')?.classList.add('hidden');state.pendingUpdate=null;await clearKadrNotifications();returnToMyHome();if(!silent)toast('✓ تم تسجيل مراجعة النسخة — يمكنك اعتمادها من إدارة كادر');return true}catch(e){console.error(e);if(!silent)toast(e.code==='CANDIDATE_CHANGED_RETEST'?'تغيّرت ملفات التحديث أثناء الاختبار؛ أعد فتح النسخة الجديدة':'تعذر تأكيد المراجعة — حاول مرة واحدة من الزر');return false}finally{candidateTestInFlight=false}}
async function stageRelease(btn=null){if(!isAdmin()||releaseActionInFlight)return;const version=$('#releaseVersion').value.trim(),notes=$('#releaseNotes').value.trim();if(!/^\d+(\.\d+){1,2}$/.test(version)||versionNumber(version)<=versionNumber(state.release.stable_version))return toast('أدخل رقم إصدار أعلى من الحالي');releaseActionInFlight=true;releaseBusy(btn||$('#stageReleaseBtn'),true,'جارٍ التحقق…');try{await releaseCall({action:'stage',version,notes,scope:'release'},{retries:2});hide('releaseModal');await waitForReleaseState(r=>r.candidate_available&&String(r.candidate_version)===version&&r.candidate_files_verified,9000);renderAdmin();toast(`✓ v${version} وصل للمالك وجاهز للاختبار`)}catch(e){console.error(e);toast(e.code==='GITHUB_NOT_READY'?'ملفات الإصدار غير مكتملة في GitHub — لم يُرسل أي إشعار':'تعذر تهيئة التحديث')}finally{releaseActionInFlight=false;releaseBusy(btn||$('#stageReleaseBtn'),false)}}
async function approveCandidateRelease(btn=null){if(!isAdmin()||!state.release?.candidate_available||releaseActionInFlight)return;if(!candidateMode()&&!state.release?.candidate_tested_at)return toast('افتح النسخة التجريبية أولًا');if(!state.release?.candidate_tested_at){const ok=await markCandidateTested({silent:true});if(!ok){await refreshReleaseState().catch(()=>{});renderAdmin();return toast('تعذر تأكيد الاختبار تلقائيًا؛ اضغط «تأكيد الاختبار» مرة واحدة')}}const version=String(state.release.candidate_version);releaseActionInFlight=true;releaseBusy(btn,true,'جارٍ الاعتماد والنشر…');try{const data=await releaseCall({action:'approve',version},{retries:2});if(data.published){state.release={...state.release,stable_version:version,candidate_available:false,candidate_status:'published'};localStorage.removeItem(CANDIDATE_TEST_KEY);localStorage.removeItem(CANDIDATE_ACK_KEY);renderAdmin();refreshReleaseUI();toast(`✓ تم اعتماد ونشر v${version} للمستخدمين`)}else{state.release={...state.release,candidate_status:'approved_waiting_publish'};renderAdmin();toast(`✓ تم اعتماد v${version} — جارٍ النشر التلقائي`);const done=await waitForReleaseState(r=>String(r.stable_version)===version&&!r.candidate_available,90000);if(String(done?.stable_version)===version&&!done?.candidate_available){renderAdmin();refreshReleaseUI();toast(`✓ تم نشر v${version} للمستخدمين تلقائيًا`)}else{renderAdmin();toast('تم الاعتماد بنجاح — سيكتمل النشر تلقائيًا دون ضغط إضافي')}}}catch(e){console.error(e);if(e.code==='CANDIDATE_CHANGED_RETEST'){await refreshReleaseState().catch(()=>{});renderAdmin();toast('تغيّرت ملفات GitHub بعد الاختبار؛ يجب فتح النسخة الجديدة مرة واحدة')}else if(e.code==='CANDIDATE_NOT_TESTED'){await refreshReleaseState().catch(()=>{});renderAdmin();toast('لم يثبت الخادم الاختبار بعد؛ اضغط تأكيد الاختبار مرة واحدة')}else toast('تعذر اعتماد التحديث الآن')}finally{releaseActionInFlight=false;releaseBusy(btn,false)}}
async function publishApprovedRelease(btn=null){if(!isAdmin()||releaseActionInFlight)return;const version=String(state.release?.candidate_version||'');if(!confirm(`نشر v${version} للمستخدمين بعد التحقق النهائي من GitHub؟`))return;releaseActionInFlight=true;releaseBusy(btn,true,'جارٍ النشر…');try{const data=await releaseCall({action:'publish'},{retries:2});await waitForReleaseState(r=>String(r.stable_version)===String(data.version)&&!r.candidate_available,10000);localStorage.setItem(UPDATE_ACCEPTED_KEY,String(data.version));renderAdmin();toast(`✓ تم نشر v${data.version}`)}catch(e){console.error(e);toast(e.code==='GITHUB_CHANGED_AFTER_APPROVAL'?'تغيّرت الملفات بعد الاعتماد؛ تم إيقاف النشر لحمايتك':'تعذر نشر التحديث')}finally{releaseActionInFlight=false;releaseBusy(btn,false)}}

